cd /tmp/dev && python3 - <<'EOF'
import sys, json, random
sys.path.insert(0,'/tmp/dev'); sys.path.insert(0,'/workspace/deps'); sys.path.insert(0,'/workspace/submission')
import t6
from common import validate, need, integer, ident, prefix, address, fields
rng = random.Random(0*977+13)
job = t6.random_campaign(rng)
print('offers', json.dumps(job['offers'])[:1200])
print('rq', job['request_quotas'])
print('oq', job['offer_quotas'])
for o in job['offers']:
    try:
        prefix(o['prefix'])
    except Exception as e:
        print('offer prefix bad', o['id'], o['prefix'], e)
for n in job['request_quotas']+job['offer_quotas']:
    if not fields(n,'id parent capacity'): print('quota fields', n)
    if not ident(n['id']): print('quota id', n)
    if not integer(n['capacity'],0,4096): print('quota cap', n)
    if n['parent'] is not None and not ident(n['parent']): print('quota parent', n)
rq={n['id']:n for n in job['request_quotas']}
oq={n['id']:n for n in job['offer_quotas']}
for r in job['requests']:
    if r['group'] not in rq: print('req group', r)
for o in job['offers']:
    if o['group'] not in oq: print('offer group', o)
    for x in o['requests']:
        if x not in {r['id'] for r in job['requests']}: print('offer unknown req', o['id'], x)
EOF
